let C : (Fin n → Ω × ℝ) → (Fin n → ℝ) := fun ω i => (η k) i ω
let D1 : (Fin n → Ω × ℝ) → ℝ := fun ω => F1 (C ω)
let D2 : (Fin n → Ω × ℝ) → ℝ := fun ω => F2 (C ω)
let A : (Fin n → Ω × ℝ) → ℝ := fun ω => FA (C ω)
let B : (Fin n → Ω × ℝ) → ℝ := fun ω => FB (C ω)
let Adelete : Fin n → (Fin n → Ω × ℝ) → ℝ := fun i ω => FAdelete i (fun j => (η k) j.1 ω)
let Bdelete : Fin n → (Fin n → Ω × ℝ) → ℝ := fun i ω => FBdelete i (fun j => (η k) j.1 ω)
let W : (Fin n → Ω × ℝ) → ℝ := fun ω => ∑ i : Fin n, (η k) i ω
let V : (Fin n → Ω × ℝ) → ℝ := fun ω => Real.sqrt (∑ i : Fin n, ((η k) i ω) ^ 2)
let S : (Fin n → Ω × ℝ) → ℝ := fun ω => ∑ i : Fin n, (z * (η k) i ω - (z * (η k) i ω) ^ 2 / 2)
let Sminus : Fin n → (Fin n → Ω × ℝ) → ℝ := fun i ω => ∑ j ∈ Finset.univ.erase i, (z * (η k) j ω - (z * (η k) j ω) ^ 2 / 2)
let I : ℝ := ∫ ω, Real.exp (S ω) ∂ν
let δ : Fin n → ℝ := fun i => ∫ ω, (z * (η k) i ω) ^ 2 * min |z * (η k) i ω| 1 ∂ν
let L : ℝ := ∑ i : Fin n, δ i
let full : (Fin n → Ω × ℝ) → ℝ := fun ω => (z * A ω + z ^ 2 * B ω) * Real.exp (S ω)
let deleted : Fin n → (Fin n → Ω × ℝ) → ℝ := fun i ω => (min |z * (η k) i ω| 1 * (|A ω - Adelete i ω| + z * |B ω - Bdelete i ω|)) * Real.exp (Sminus i ω)
let R : ℝ := ((∫ ω, full ω ∂ν) + ∑ i : Fin n, ∫ ω, deleted i ω ∂ν) / I
let T : (Fin n → Ω × ℝ) → ℝ := fun ω => (W ω + D1 ω) / (V ω * Real.sqrt (1 + D2 ω))
(∀ ω : (Fin n → Ω × ℝ), 0 ≤ A ω ∧ 0 ≤ B ω) →
(∀ (i : Fin n) (ω : (Fin n → Ω × ℝ)), 0 ≤ Adelete i ω ∧ 0 ≤ Bdelete i ω) →
(∀ᵐ ω ∂ν, |D1 ω| ≤ A ω ∧ |D2 ω| ≤ B ω) →
(∀ᵐ ω ∂ν, 0 < 1 + D2 ω) →
(∀ᵐ ω ∂ν, 0 < V ω) →
Integrable (fun ω => Real.exp (S ω)) ν →
0 < I → Integrable full ν →
(∀ i : Fin n, Integrable (deleted i) ν) →
1 ≤ z → (∀ i : Fin n, δ i ≤ 1) → L ≤ cSZ * z ^ 2 →
Shao.standardNormalTail z * Real.exp (-C1 * L) * (1 - C2 * R) ≤
  ν.real {ω : (Fin n → Ω × ℝ) | z ≤ T ω} ∧
ν.real {ω : (Fin n → Ω × ℝ) | z ≤ T ω} ≤
  Shao.standardNormalTail z * Real.exp (C3 * L) * (1 + C4 * R) +
    ν.real {ω : (Fin n → Ω × ℝ) | z * |D1 ω| > V ω / 4} +
    ν.real {ω : (Fin n → Ω × ℝ) | z ^ 2 * |D2 ω| > (1 / 4 : ℝ)}

